draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // book
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/2-50, H/2-70, 100, 20);
  ctx.fillStyle = 'white';
  ctx.fillRect(W/2-45, H/2-65, 90, 10);
  ctx.strokeRect(W/2-50, H/2-70, 100, 20);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-20, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-10);
  ctx.lineTo(W/2, H/2+20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2-20, H/2+20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2+20, H/2+20);
  ctx.stroke();

  // wisdom bubble
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2+40, H/2-60, 20+10*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.font = '14px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply', W/2+40, H/2-60);

  ctx.restore();
}
